### 3. API Endpoint

```python
# routes/preferences.py
from flask import Blueprint, jsonify, request
from models import db, UserPreference
from auth import token_required

preferences_bp = Blueprint('preferences', __name__)

@preferences_bp.route('/api/user/preferences', methods=['GET'])
@token_required
def get_user_preferences(current_user):
    """
    Get user preference settings

    Returns:
        JSON response with user preferences or error message
    """
    try:
        # Get or create preferences for the user
        preferences = UserPreference.query.filter_by(user_id=current_user.id).first()

        # If preferences don't exist, create default preferences
        if not preferences:
            preferences = UserPreference(user_id=current_user.id)
            db.session.add(preferences)
            db.session.commit()

        return jsonify({
            'success': True,
            'data': preferences.to_dict()
        }), 200

    except Exception as e:
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to retrieve user preferences',
            'message': str(e)
        }), 500

@preferences_bp.route('/api/user/preferences', methods=['PUT'])
@token_required
def update_user_preferences(current_user):
    """
    Update user preference settings

    Request Body:
        theme: string (optional)
        language: string (optional)
        timezone: string (optional)
        notifications: object (optional)

    Returns:
        JSON response with updated preferences or error message
    """
    try:
        data = request.get_json()

        if not data:
            return jsonify({
                'success': False,
                'error': 'No data provided'
            }), 400

        preferences = UserPreference.query.filter_by(user_id=current_user.id).first()

        if not preferences:
            preferences = UserPreference(user_id=current_user.id)
            db.session.add(preferences)

        # Update only provided fields
        if 'theme' in data:
            if data['theme'] not in ['light', 'dark', 'auto']:
                return jsonify({
                    'success': False,
                    'error': 'Invalid theme value. Must be: light, dark, or auto'
                }), 400
            preferences.theme = data['theme']

        if 'language' in data:
            preferences.language = data['language']

        if 'timezone' in data:
            preferences.timezone = data['timezone']

        if 'notifications' in data:
            if not isinstance(data['notifications'], dict):
                return jsonify({
                    'success': False,
                    'error': 'Notifications must be an object'
                }), 400
            preferences.notifications = data['notifications']

        db.session.commit()

        return jsonify({
            'success': True,
            'data': preferences.to_dict()
        }), 200

    except Exception as e:
        db.session.rollback()
        return jsonify({
            'success': False,
            'error': 'Failed to update user preferences',
            'message': str(e)
        }), 500
