### 2. API Service

```typescript
// services/preferences.service.ts

import {
  UserPreferences,
  PreferencesResponse,
  UpdatePreferencesPayload,
  PreferencesError
} from '../types/preferences.types';

class PreferencesService {
  private baseURL: string;
  private tokenKey: string;

  constructor(baseURL: string = 'http://localhost:5000', tokenKey: string = 'auth_token') {
    this.baseURL = baseURL;
    this.tokenKey = tokenKey;
  }

  /**
   * Get authentication token from storage
   */
  private getToken(): string | null {
    return localStorage.getItem(this.tokenKey);
  }

  /**
   * Build headers with authentication
   */
  private getHeaders(): HeadersInit {
    const headers: HeadersInit = {
      'Content-Type': 'application/json',
    };

    const token = this.getToken();
    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    return headers;
  }

  /**
   * Handle API response
   */
  private async handleResponse<T>(response: Response): Promise<T> {
    const data = await response.json();

    if (!response.ok) {
      throw new PreferencesError(
        data.error || 'An error occurred',
        response.status,
        data
      );
    }

    return data;
  }

  /**
   * Get user preferences
   * @returns Promise with user preferences
   * @throws PreferencesError
   */
  async getPreferences(): Promise<UserPreferences> {
    try {
      const response = await fetch(`${this.baseURL}/api/user/preferences`, {
        method: 'GET',
        headers: this.getHeaders(),
      });

      const data = await this.handleResponse<PreferencesResponse>(response);

      if (!data.success || !data.data) {
        throw new PreferencesError('Failed to retrieve preferences');
      }

      return data.data;
    } catch (error) {
      if (error instanceof PreferencesError) {
        throw error;
      }
      throw new PreferencesError(
        'Network error: Unable to fetch preferences',
        undefined,
        error
      );
    }
  }

  /**
   * Update user preferences
   * @param updates - Partial preferences to update
   * @returns Promise with updated preferences
   * @throws PreferencesError
   */
  async updatePreferences(
    updates: UpdatePreferencesPayload
  ): Promise<UserPreferences> {
    try {
      const response = await fetch(`${this.baseURL}/api/user/preferences`, {
        method: 'PUT',
        headers: this.getHeaders(),
        body: JSON.stringify(updates),
      });

      const data = await this.handleResponse<PreferencesResponse>(response);

      if (!data.success || !data.data) {
        throw new PreferencesError('Failed to update preferences');
      }

      return data.data;
    } catch (error) {
      if (error instanceof PreferencesError) {
        throw error;
      }
      throw new PreferencesError(
        'Network error: Unable to update preferences',
        undefined,
        error
      );
    }
  }

  /**
   * Update theme preference
   * @param theme - Theme value
   */
  async updateTheme(theme: 'light' | 'dark' | 'auto'): Promise<UserPreferences> {
    return this.updatePreferences({ theme });
  }

  /**
   * Update language preference
   * @param language - Language code
   */
  async updateLanguage(language: string): Promise<UserPreferences> {
    return this.updatePreferences({ language });
  }

  /**
   * Update timezone preference
   * @param timezone - Timezone string
   */
  async updateTimezone(timezone: string): Promise<UserPreferences> {
    return this.updatePreferences({ timezone });
  }
}

export default new PreferencesService();
```

### 3. React Hook (Optional but useful)

```typescript
// hooks/usePreferences.ts

import { useState, useEffect, useCallback } from 'react';
import preferencesService from '../services/preferences.service';
import {
  UserPreferences,
  UpdatePreferencesPayload,
  PreferencesError
} from '../types/preferences.types';

interface UsePreferencesReturn {
  preferences: UserPreferences | null;
  loading: boolean;
  error: PreferencesError | null;
  refetch: () => Promise<void>;
  updatePreferences: (updates: UpdatePreferencesPayload) => Promise<void>;
}

export const usePreferences = (): UsePreferencesReturn => {
  const [preferences, setPreferences] = useState<UserPreferences | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<PreferencesError | null>(null);

  const fetchPreferences = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await preferencesService.getPreferences();
      setPreferences(data);
    } catch (err) {
      setError(err as PreferencesError);
    } finally {
      setLoading(false);
    }
  }, []);

  const updatePreferences = useCallback(
    async (updates: UpdatePreferencesPayload) => {
      try {
        setError(null);
        const data = await preferencesService.updatePreferences(updates);
        setPreferences(data);
      } catch (err) {
        setError(err as PreferencesError);
        throw err;
      }
    },
    []
  );

  useEffect(() => {
    fetchPreferences();
  }, [fetchPreferences]);

  return {
    preferences,
    loading,
    error,
    refetch: fetchPreferences,
    updatePreferences,
  };
};
```

### 4. Usage Example (React Component)

```typescript
// components/PreferencesPanel.tsx

import React, { useState } from 'react';
import { usePreferences } from '../hooks/usePreferences';
import type { NotificationPreferences } from '../types/preferences.types';

const PreferencesPanel: React.FC = () => {
  const { preferences, loading, error, updatePreferences } = usePreferences();
  const [saving, setSaving] = useState(false);

  const handleThemeChange = async (theme: 'light' | 'dark' | 'auto') => {
    try {
      setSaving(true);
      await updatePreferences({ theme });
    } catch (err) {
      console.error('Failed to update theme:', err);
    } finally {
      setSaving(false);
    }
  };

  const handleLanguageChange = async (language: string) => {
    try {
      setSaving(true);
      await updatePreferences({ language });
    } catch (err) {
      console.error('Failed to update language:', err);
    } finally {
      setSaving(false);
    }
  };

  const handleNotificationChange = async (
    key: keyof NotificationPreferences,
    value: boolean
  ) => {
    if (!preferences) return;

    try {
      setSaving(true);
      await updatePreferences({
        notifications: {
          ...preferences.notifications,
          [key]: value,
        },
      });
    } catch (err) {
      console.error('Failed to update notifications:', err);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <div className="preferences-panel">Loading preferences...</div>;
  }

  if (error) {
    return (
      <div className="preferences-panel error">
        <h3>Error Loading Preferences</h3>
        <p>{error.message}</p>
        {error.statusCode === 401 && <p>Please log in again.</p>}
      </div>
    );
  }

  if (!preferences) {
    return <div className="preferences-panel">No preferences available</div>;
  }

  return (
    <div className="preferences-panel">
      <h2>User Preferences</h2>

      {/* Theme Selection */}
      <div className="preference-section">
        <h3>Theme</h3>
        <select
          value={preferences.theme}
          onChange={(e) => handleThemeChange(e.target.value as any)}
          disabled={saving}
        >
          <option value="light">Light</option>
          <option value="dark">Dark</option>
          <option value="auto">Auto</option>
        </select>
      </div>

      {/* Language Selection */}
      <div className="preference-section">
        <h3>Language</h3>
        <select
          value={preferences.language}
          onChange={(e) => handleLanguageChange(e.target.value)}
          disabled={saving}
        >
          <option value="en">English</option>
          <option value="es">Español</option>
          <option value="fr">Français</option>
          <option value="de">Deutsch</option>
        </select>
      </div>

      {/* Timezone Selection */}
      <div className="preference-section">
        <h3>Timezone</h3>
        <input
          type="text"
          value={preferences.timezone}
          onChange={(e) => updatePreferences({ timezone: e.target.value })}
          disabled={saving}
        />
      </div>

      {/* Notification Preferences */}
      <div className="preference-section">
        <h3>Notifications</h3>
        <label>
          <input
            type="checkbox"
            checked={preferences.notifications.email}
            onChange={(e) => handleNotificationChange('email', e.target.checked)}
            disabled={saving}
          />
          Email Notifications
        </label>
        <label>
          <input
            type="checkbox"
            checked={preferences.notifications.push}
            onChange={(e) => handleNotificationChange('push', e.target.checked)}
            disabled={saving}
          />
          Push Notifications
        </label>
        <label>
          <input
            type="checkbox"
            checked={preferences.notifications.sms}
            onChange={(e) => handleNotificationChange('sms', e.target.checked)}
            disabled={saving}
          />
          SMS Notifications
        </label>
      </div>

      {saving && <div className="saving-indicator">Saving...</div>}
    </div>
  );
};

export default PreferencesPanel;
```

