    });

    it('should throw PreferencesError on validation error', async () => {
      (fetch as jest.Mock).mockResolvedValueOnce({
        ok: false,
        status: 400,
        json: async () => ({
          error: 'Invalid theme value. Must be: light, dark, or auto',
        }),
